// The read schema the deployment was built against (db/build-chain-schema.mjs). Every deployment
// profile pins its hash (`CHAIN.readSchema`, db/prepare-chain-deployment.mjs); the chain client
// refuses reads when the profile and this schema disagree.
import * as current from './generated/index.js';

export const CURRENT_SCHEMA_HASH = current.SCHEMA_HASH;
export function hasSchema(name) { return current.hasSchema(name); }
export function loadSchema(name) { return current.loadSchema(name); }
